import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.CjAa9jTu.js";const p=JSON.parse('{"title":"Arquitectura Cortex-M y firmware","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cortex-m.md","filePath":"guide/cortex-m.md"}'),i={name:"guide/cortex-m.md"};function n(d,e,l,s,c,m){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="arquitectura-cortex-m-y-firmware" tabindex="-1">Arquitectura Cortex-M y firmware <a class="header-anchor" href="#arquitectura-cortex-m-y-firmware" aria-label="Permalink to &quot;Arquitectura Cortex-M y firmware&quot;">​</a></h1><h2 id="del-codigo-al-comportamiento" tabindex="-1">Del código al comportamiento <a class="header-anchor" href="#del-codigo-al-comportamiento" aria-label="Permalink to &quot;Del código al comportamiento&quot;">​</a></h2><p><strong>Cortex-M</strong> es una familia de núcleos de procesamiento para microcontroladores. El <strong>PY32F003L24D6TR</strong> integra un núcleo <strong>Cortex-M0+</strong>, memoria y periféricos en el mismo circuito. La placa DevLab añade conexiones, regulación de tensión, LED y botón de reinicio.</p><h2 id="que-ocurre-al-ejecutar-un-programa" tabindex="-1">Qué ocurre al ejecutar un programa <a class="header-anchor" href="#que-ocurre-al-ejecutar-un-programa" aria-label="Permalink to &quot;Qué ocurre al ejecutar un programa&quot;">​</a></h2><ol><li>El compilador transforma C/C++ en instrucciones para el núcleo ARM.</li><li>El enlazador ubica código y datos en las regiones de memoria disponibles.</li><li>El programador carga el firmware en Flash mediante SWD.</li><li>Tras el reinicio, el código de arranque prepara la ejecución.</li><li>El entorno Arduino llama una vez a <code>setup()</code> y repite <code>loop()</code>.</li></ol><p>El <strong>firmware</strong> es el programa que ejecuta el microcontrolador para controlar su hardware. Una llamada como <code>digitalWrite(PB5, HIGH)</code> termina configurando el periférico GPIO que gobierna el LED.</p><h2 id="memoria-del-dispositivo-del-taller" tabindex="-1">Memoria del dispositivo del taller <a class="header-anchor" href="#memoria-del-dispositivo-del-taller" aria-label="Permalink to &quot;Memoria del dispositivo del taller&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recurso</th><th>Capacidad</th><th>Qué contiene</th></tr></thead><tbody><tr><td>Flash</td><td>16 KB</td><td>Programa y datos que deben conservarse sin alimentación</td></tr><tr><td>SRAM</td><td>2 KB</td><td>Variables de trabajo, búferes, pila y memoria dinámica</td></tr></tbody></table><p>La <strong>pila</strong> guarda, entre otros datos, variables locales y el contexto de las llamadas. La <strong>memoria dinámica</strong> se reserva durante la ejecución. Ambas comparten la RAM con las variables estáticas: el resumen de compilación no predice todo el consumo durante el funcionamiento.</p><p>Estas capacidades corresponden a <strong>PY32F003L24D6</strong>, según la tabla 1-4 de la <a href="/unit_devlab_cortex_m_examples/py32f003/PY32F003_Datasheet_Rev1.7.pdf">hoja de datos</a>.</p><h2 id="reloj-temporizadores-e-interrupciones" tabindex="-1">Reloj, temporizadores e interrupciones <a class="header-anchor" href="#reloj-temporizadores-e-interrupciones" aria-label="Permalink to &quot;Reloj, temporizadores e interrupciones&quot;">​</a></h2><p>El taller utiliza el oscilador interno <strong>HSI a 24 MHz</strong>. Los temporizadores cuentan pulsos de reloj para medir intervalos o generar señales. Una interrupción permite atender un evento y después volver al programa principal.</p><p>Arduino ofrece funciones como <code>delay()</code> y <code>millis()</code> para comenzar sin configurar directamente todos los registros. Al estudiar sus resultados, relaciona la configuración de reloj con los tiempos observados.</p><h2 id="perifericos" tabindex="-1">Periféricos <a class="header-anchor" href="#perifericos" aria-label="Permalink to &quot;Periféricos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Periférico</th><th>Ejemplo de uso</th></tr></thead><tbody><tr><td>GPIO</td><td>Leer un pulsador y encender el LED</td></tr><tr><td>ADC</td><td>Convertir la tensión de un potenciómetro en un número</td></tr><tr><td>UART</td><td>Enviar registros a la computadora</td></tr><tr><td>I²C</td><td>Comunicarse con un sensor mediante dirección</td></tr><tr><td>SPI</td><td>Intercambiar datos con un dispositivo seleccionado por CS</td></tr></tbody></table><p>El encapsulado de ocho terminales comparte varias funciones en una misma conexión física. Consulta el <a href="./../py32f003-getting-started/03_pinout">pinout</a> antes de intentar utilizar varios periféricos a la vez.</p><p><strong>Siguiente tema:</strong> <a href="./compilacion">Compilación y memoria</a>.</p>',17)])])}const h=a(i,[["render",n]]);export{p as __pageData,h as default};
